from scipy.optimize import least_squares
fams={
 'Holl_harvest': lambda p: p[0]*P*(1-P/p[1]) - p[2]*P/(p[3]+P),
 'Allee_const': lambda p: p[0]*P*(P/p[1]-1)*(1-P/p[2]) - p[3],
 'logis_harv_const': lambda p: p[0]*P*(1-P/p[1]) - p[2] - p[3]*P,
 'Hill_harv': lambda p: p[0]*P*(1-P/p[1]) - p[2]*P**2/(p[3]**2+P**2),
 'quad_exp': lambda p: p[0]*P + p[1]*P**2 + p[2] + p[3]*np.exp(-P)+p[4]*P*np.exp(-P),
 'Gomp_harv': lambda p: p[0]*P*np.log(p[1]/P) - p[2],
 'Richards': lambda p: p[0]*P*(1-(P/p[1])**p[2]) - p[3],
 'Expo_harv': lambda p: p[0]*P*(1-P/p[1]) - p[2]*(1-np.exp(-P/p[3])),
}
best={}
for name,f in fams.items():
    bestc=None
    for s in range(12):
        rng=np.random.default_rng(s)
        p0=rng.uniform(0.5,5,size=5)
        try:
            res=least_squares(lambda p: f(p)-dP_dt, p0)
            if bestc is None or res.cost<bestc.cost: bestc=res
        except Exception as e: pass
    if bestc is not None:
        print(name, np.std(bestc.fun), np.round(bestc.x,4))

